update oa_sign_package_document
template_id = #{templateId}, template_type = #{templateType}, document_name = #{documentName}, template_version_snapshot = #{templateVersionSnapshot}, source_file_url_snapshot = #{sourceFileUrlSnapshot}, generated_file_url = #{generatedFileUrl}, generated_pdf_url = #{generatedPdfUrl}, signed_file_url = #{signedFileUrl}, certificate_file_url = #{certificateFileUrl}, file_hash_before_sign = #{fileHashBeforeSign}, file_hash_after_sign = #{fileHashAfterSign}, review_pdf_url = #{reviewPdfUrl}, review_pdf_hash = #{reviewPdfHash}, signed_pdf_url = #{signedPdfUrl}, signed_pdf_hash = #{signedPdfHash}, final_pdf_url = #{finalPdfUrl}, final_pdf_hash = #{finalPdfHash}, final_content_hash = #{finalContentHash}, final_archive_pdf_url = #{finalArchivePdfUrl}, final_archive_pdf_hash = #{finalArchivePdfHash}, signature_file_url = #{signatureFileUrl}, signature_hash = #{signatureHash}, certificate_hash = #{certificateHash}, document_version = #{documentVersion}, final_document_version = #{finalDocumentVersion}, final_read_confirmed = #{finalReadConfirmed}, final_read_confirmed_time = #{finalReadConfirmedTime}, read_confirmed = #{readConfirmed}, signed = #{signed}, sort_order = #{sortOrder}, status = #{status}, error_message = #{errorMessage}, remark = #{remark}, update_time = sysdate()
where document_id = #{documentId}

update oa_sign_package_document
set final_read_confirmed = 'Y',
    final_read_confirmed_time = coalesce(final_read_confirmed_time, #{confirmedTime}),
    update_time = sysdate()
where document_id = #{documentId}
  and package_id = #{packageId}
  and final_document_version = #{finalDocumentVersion}
  and final_pdf_hash = #{finalPdfHash}
  and employee_visible = 'Y'
  and final_pdf_url is not null
